563	/// Scan all markdown notes and extract recording metadata.
564	pub fn collect_recording_notes(root: &Path) -> Result<Vec<RecordingNoteInfo>, String> {
565	    let mut note_files = Vec::new();
566	    collect_markdown_note_files(root, root, &mut note_files)?;
567	    let mut recordings = Vec::new();
568	    for note_path in note_files {
569	        let raw = match fs::read_to_string(&note_path) {
570	            Ok(value) => value,
571	            Err(_) => continue,
572	        };
573	        let (meta, _) = parse_note_front_matter(&raw);
574	        let note_rel = strip_root(root, &note_path);
575	        if let Some(info) = recording_info_from_note_meta(root, &note_path, &note_rel, &meta) {
576	            recordings.push(info);
577	        }
578	    }
579	    Ok(recordings)
580	}
