709	/// Start a background worker thread if jobs are queued and none is running.
710	pub fn spawn_transcription_worker_if_needed() {
711	    let should_spawn = {
712	        let queue = transcription_queue_state();
713	        let mut state = queue.lock().expect("transcription queue poisoned");
714	        if state.running || state.pending.is_empty() {
715	            false
716	        } else {
717	            state.running = true;
718	            true
719	        }
720	    };
721	    if !should_spawn {
722	        return;
723	    }
724	    thread::spawn(move || loop {
725	        let maybe_job = {
726	            let queue = transcription_queue_state();
727	            let mut state = queue.lock().expect("transcription queue poisoned");
728	            match state.pending.pop_front() {
729	                Some(job) => {
730	                    state.current_recording = Some(job.note_rel.clone());
731	                    Some(job)
732	                }
733	                None => {
734	                    state.running = false;
735	                    state.current_recording = None;
736	                    None
737	                }
738	            }
739	        };
740	        let Some(job) = maybe_job else {
741	            break;
742	        };
743	        process_transcription_job(job.clone());
744	        let queue = transcription_queue_state();
745	        let mut state = queue.lock().expect("transcription queue poisoned");
746	        state.known_recordings.remove(&job.note_rel);
747	        if state.current_recording.as_deref() == Some(job.note_rel.as_str()) {
748	            state.current_recording = None;
749	        }
750	    });
751	}
