779	/// Scan the recording notes under `root` and enqueue every transcribable one
780	/// with a clone of `method`; the shared sequential worker picks them up.
781	fn queue_recordings_with_method(
782	    root: &Path,
783	    method: &TranscriptionMethod,
784	) -> Result<RecordingTranscriptionQueueResult, String> {
785	    let recordings = collect_recording_notes(root)?;
786	    let active_recordings = active_transcription_note_paths();
787	    let mut scanned = 0usize;
788	    let mut skipped = 0usize;
789	    let mut candidates = Vec::new();
790	
791	    for recording in recordings {
792	        scanned += 1;
793	        if !recording.audio_path.exists() {
794	            let _ = update_recording_note_status(
795	                &recording.note_path,
796	                RECORDING_STATUS_FAILED,
797	                Some("Audio file is missing.".to_string()),
798	                None,
799	                None,
800	            );
801	            skipped += 1;
802	            continue;
803	        }
804	
805	        let status = recording.status.as_str();
806	        let is_active = active_recordings.contains(&recording.note_rel);
807	
808	        if status == RECORDING_STATUS_COMPLETED {
809	            skipped += 1;
810	            continue;
811	        }
812	
813	        if matches!(
814	            status,
815	            crate::RECORDING_STATUS_QUEUED | RECORDING_STATUS_PROCESSING
816	        ) && is_active
817	        {
818	            skipped += 1;
819	            continue;
820	        }
821	
822	        update_recording_note_status(
823	            &recording.note_path,
824	            crate::RECORDING_STATUS_QUEUED,
825	            None,
826	            None,
827	            None,
828	        )?;
829	        candidates.push(QueuedTranscriptionJob {
830	            note_rel: recording.note_rel,
831	            note_path: recording.note_path,
832	            audio_path: recording.audio_path,
833	            method: method.clone(),
834	        });
835	    }
836	
837	    let queued = {
838	        let queue = transcription_queue_state();
839	        let mut state = queue.lock().expect("transcription queue poisoned");
840	        let mut added = 0usize;
841	        for job in candidates {
842	            if state.known_recordings.contains(&job.note_rel) {
843	                continue;
844	            }
845	            state.known_recordings.insert(job.note_rel.clone());
846	            state.pending.push_back(job);
847	            added += 1;
848	        }
849	        added
850	    };
851	
852	    spawn_transcription_worker_if_needed();
853	    let in_flight = recording_queue_snapshot().in_flight;
854	
855	    Ok(RecordingTranscriptionQueueResult {
856	        scanned,
857	        queued,
858	        skipped,
859	        in_flight,
860	    })
861	}
