1	import { useEffect, useMemo, useRef } from "react";
2	import { EditorContent, useEditor } from "@tiptap/react";
3	import StarterKit from "@tiptap/starter-kit";
4	import Placeholder from "@tiptap/extension-placeholder";
5	import { joinFrontmatter, splitFrontmatter } from "@typenotes/shared/frontmatter";
6	import { stripInlineAnnotationMetadata } from "@typenotes/shared/annotation-metadata";
7	import {
8	  appendRawLensBackmatterBlock,
9	  splitLensBackmatterBlock,
10	} from "@typenotes/shared/lens-backmatter";
11	import { htmlToMarkdown, markdownToHtml } from "../lib/markdown-editor";
12	
13	type NoteEditorProps = {
14	  markdown: string;
15	  onChange: (markdown: string) => void;
16	};
17	
18	const toolbarButton =
19	  "rounded-md border border-transparent px-2 py-1 text-xs font-medium text-[var(--ui-muted)] transition-colors hover:border-[var(--ui-border)] hover:bg-[var(--ui-select)] hover:text-[var(--ui-text)]";
20	
21	const splitEditorMarkdown = (markdown: string) => {
22	  const split = splitFrontmatter(markdown);
23	  const lensSplit = splitLensBackmatterBlock(split.body);
24	  return {
25	    frontmatterBlock: split.frontmatterBlock,
26	    backmatterBlock: lensSplit.rawBlock,
27	    body: stripInlineAnnotationMetadata(lensSplit.content),
28	  };
29	};
30	
31	export function NoteEditor({ markdown, onChange }: NoteEditorProps) {
32	  const isSyncing = useRef(false);
33	  const latestMarkdown = useRef(markdown);
34	  const scrollRef = useRef<HTMLDivElement | null>(null);
35	  const initialContentRef = useRef(splitEditorMarkdown(markdown));
36	  const frontmatterRef = useRef<string | null>(initialContentRef.current.frontmatterBlock);
37	  const backmatterRef = useRef<string | null>(initialContentRef.current.backmatterBlock);
38	
39	  const keepCaretBreathingRoom = (currentEditor: NonNullable<ReturnType<typeof useEditor>>) => {
40	    const scrollEl = scrollRef.current;
41	    if (!scrollEl) {
42	      return;
43	    }
44	    const position = currentEditor.state.selection.$anchor.pos;
45	    let coords: { top: number; bottom: number };
46	    try {
47	      coords = currentEditor.view.coordsAtPos(position);
48	    } catch {
49	      return;
50	    }
51	    const rect = scrollEl.getBoundingClientRect();
52	    const bottomLimit = rect.bottom - rect.height * 0.2;
53	    if (coords.bottom <= bottomLimit) {
54	      return;
55	    }
56	    const delta = coords.bottom - bottomLimit;
57	    const maxScrollTop = scrollEl.scrollHeight - scrollEl.clientHeight;
58	    scrollEl.scrollTop = Math.min(maxScrollTop, scrollEl.scrollTop + delta);
59	  };
60	
61	  const extensions = useMemo(
62	    () => [
63	      StarterKit.configure({
64	        heading: { levels: [1, 2, 3] },
65	      }),
66	      Placeholder.configure({
67	        placeholder: "What's on your mind?",
68	      }),
69	    ],
70	    []
71	  );
72	
73	  const editor = useEditor({
74	    extensions,
75	    autofocus: false,
76	    enableInputRules: false,
77	    content: markdownToHtml(initialContentRef.current.body),
78	    editorProps: {
79	      attributes: {
80	        class: "tiptap-content",
81	      },
82	    },
83	    onUpdate: ({ editor: currentEditor }) => {
84	      if (isSyncing.current) {
85	        return;
86	      }
87	      const nextBodyMarkdown = htmlToMarkdown(currentEditor.getHTML());
88	      const frontmatterJoined = joinFrontmatter(frontmatterRef.current, nextBodyMarkdown);
89	      const nextMarkdown = appendRawLensBackmatterBlock(
90	        frontmatterJoined,
91	        backmatterRef.current
92	      );
93	      latestMarkdown.current = nextMarkdown;
94	      onChange(nextMarkdown);
95	      requestAnimationFrame(() => keepCaretBreathingRoom(currentEditor));
96	    },
97	  });
98	
99	  useEffect(() => {
100	    if (!editor) {
101	      return;
102	    }
103	    if (markdown === latestMarkdown.current) {
104	      return;
105	    }
106	    const incoming = splitEditorMarkdown(markdown);
107	    frontmatterRef.current = incoming.frontmatterBlock;
108	    backmatterRef.current = incoming.backmatterBlock;
109	    const currentBodyMarkdown = htmlToMarkdown(editor.getHTML());
110	    if (currentBodyMarkdown === incoming.body) {
111	      latestMarkdown.current = markdown;
112	      return;
113	    }
114	    isSyncing.current = true;
115	    editor.commands.setContent(markdownToHtml(incoming.body), { emitUpdate: false });
116	    isSyncing.current = false;
117	    latestMarkdown.current = markdown;
118	  }, [editor, markdown]);
119	
120	  if (!editor) {
121	    return (
122	      <div className="flex h-full items-center justify-center text-sm text-[var(--ui-muted)]">
123	        Loading editor...
124	      </div>
125	    );
126	  }
127	
128	  return (
129	    <div className="tiptap-editor">
130	      <div className="tiptap-toolbar">
131	        <button
132	          type="button"
133	          className={`${toolbarButton}${editor.isActive("bold") ? " is-active" : ""}`}
134	          onClick={() => editor.chain().focus().toggleBold().run()}
135	        >
136	          Bold
137	        </button>
138	        <button
139	          type="button"
140	          className={`${toolbarButton}${editor.isActive("italic") ? " is-active" : ""}`}
141	          onClick={() => editor.chain().focus().toggleItalic().run()}
142	        >
143	          Italic
144	        </button>
145	        <button
146	          type="button"
147	          className={`${toolbarButton}${editor.isActive("heading", { level: 1 }) ? " is-active" : ""}`}
148	          onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()}
149	        >
150	          H1
151	        </button>
