1	//! Apple Notes import.
2	//!
3	//! Imports an *exported* Apple Notes folder tree into the active profile's notes
4	//! root. Apple Notes has no native bulk export, so users export with a tool such
5	//! as the free "Exporter" app, which produces a nested folder of Markdown (and
6	//! sometimes HTML / plain-text) files. This adapter walks that tree and creates
7	//! app notes, preserving each note's original creation date.
8	//!
9	//! Two modes:
10	//!   * `preserve` — recreate the source folder hierarchy under a single target
11	//!                  folder in the notes root.
12	//!   * `flatten`  — drop every note directly into `Feed`, discarding hierarchy.
13	//!
14	//! Creation dates come from YAML front-matter (`created` / `date` / `created_ms`
15	//! …) when present, otherwise the source file's filesystem timestamps.
16	//!
17	//! Progress is exposed via a process-global snapshot that the frontend polls —
18	//! matching the recordings/handwriting queue pattern (the app uses no Tauri
19	//! events). The actual work runs on a detached worker thread spawned by the
20	//! command layer; only the resolved notes root + args cross the boundary, so the
21	//! worker never touches the `AppHandle`. Body encryption still works because
22	//! `write_note_with_front_matter` reads the unlocked key from the global
23	//! security runtime.
24	
25	use crate::AppEnv;
26	use crate::ports::import::ImportGateway;
27	use crate::*;
28	use serde::{Deserialize, Serialize};
29	use std::path::Path;
30	use std::sync::{Mutex, OnceLock};
31	use time::format_description::well_known::Rfc3339;
32	use time::macros::format_description;
33	use time::{Date, OffsetDateTime, PrimitiveDateTime};
34	
35	/// File extensions we treat as importable note text.
36	const TEXT_EXTENSIONS: &[&str] = &["md", "markdown", "txt", "text", "html", "htm"];
37	/// Front-matter keys that may carry the original creation date, in priority order.
38	const CREATED_KEYS: &[&str] = &[
39	    "created_ms",
40	    "created",
41	    "creationdate",
42	    "created_at",
43	    "date",
44	    "created-date",
45	];
46	/// Cap on per-note errors retained for the UI so a pathological import can't grow
47	/// the snapshot without bound.
48	const MAX_TRACKED_ERRORS: usize = 25;
49	/// Default target folder when preserving structure and no name is supplied.
50	const DEFAULT_IMPORT_FOLDER: &str = "Imported Notes";
51	
52	/// Core import gateway. Resolving the active profile and spawning the
53	/// worker are adapter concerns because both depend on process/runtime state.
54	pub struct ImportAdapter {
55	    app: AppEnv,
56	}
57	
58	impl ImportAdapter {
59	    pub fn new(app: AppEnv) -> Self {
60	        Self { app }
61	    }
62	}
63	
64	impl ImportGateway for ImportAdapter {
65	    type Scan = AppleImportScan;
66	    type Args = AppleImportArgs;
67	    type State = AppleImportState;
68	
69	    fn scan(&self, path: &str) -> Result<Self::Scan, String> {
70	        scan_apple_import_source(Path::new(path.trim()))
71	    }
72	
73	    fn start(&self, args: Self::Args) -> Result<(), String> {
74	        let notes_root = ensured_notes_root(&self.app)?;
75	        let target_label = match args.mode {
76	            AppleImportMode::Flatten => "Feed".to_string(),
77	            AppleImportMode::Preserve => args
78	                .target_folder
79	                .as_deref()
80	                .map(str::trim)
81	                .filter(|value| !value.is_empty())
82	                .map(str::to_string)
83	                .unwrap_or_else(|| "Imported Notes".to_string()),
84	        };
85	        begin_apple_import(target_label)?;
86	        std::thread::spawn(move || run_apple_notes_import(notes_root, args));
87	        Ok(())
88	    }
89	
90	    fn status(&self) -> Result<Self::State, String> {
91	        Ok(apple_import_snapshot())
92	    }
93	}
94	
95	// ── DTOs ─────────────────────────────────────────────────────────────────────
96	
97	/// Preview of an export folder, returned before the import runs.
98	#[derive(Clone, Serialize)]
99	pub struct AppleImportScan {
100	    /// Number of importable note files found (recursive).
101	    pub note_count: u32,
102	    /// Number of distinct sub-folders that contain notes.
103	    pub folder_count: u32,
104	    /// Non-text files skipped (attachments, images, …).
105	    pub skipped_files: u32,
106	    /// Base name of the chosen folder — the default target-folder suggestion.
107	    pub source_name: String,
108	    /// A handful of note titles, so the UI can show what will be imported.
109	    pub sample_titles: Vec<String>,
110	}
111	
112	/// Whether to mirror the source hierarchy or collapse everything into Feed.
113	#[derive(Clone, Copy, Deserialize, PartialEq, Eq)]
114	#[serde(rename_all = "snake_case")]
115	pub enum AppleImportMode {
116	    Preserve,
117	    Flatten,
118	}
119	
120	/// Arguments for an import run.
121	#[derive(Deserialize)]
122	pub struct AppleImportArgs {
123	    pub source_path: String,
124	    pub mode: AppleImportMode,
125	    /// Target folder name for `preserve` mode. Defaults to the source base name.
126	    #[serde(default)]
127	    pub target_folder: Option<String>,
128	    /// New-note filename strategy (mirrors the active profile setting).
129	    #[serde(default)]
130	    pub file_name_format: NoteFileNameFormat,
131	}
132	
133	/// Live, pollable progress for the current/last import.
134	#[derive(Clone, Default, Serialize)]
135	pub struct AppleImportState {
136	    pub running: bool,
137	    pub done: bool,
138	    pub total: u32,
139	    pub processed: u32,
140	    pub imported: u32,
141	    pub skipped: u32,
142	    pub failed: u32,
143	    pub folders_created: u32,
144	    /// Title of the note currently being written.
145	    pub current: String,
146	    /// Resolved destination folder (for the UI summary).
147	    pub target_folder: String,
148	    /// Fatal error that aborted the whole run, if any.
149	    pub error: Option<String>,
150	    /// Sample of per-note failures (capped at `MAX_TRACKED_ERRORS`).
151	    pub errors: Vec<String>,
152	}
153	
154	// ── Progress state ─────────────────────────────────────────────────────────────
155	
156	fn import_state() -> &'static Mutex<AppleImportState> {
157	    static STATE: OnceLock<Mutex<AppleImportState>> = OnceLock::new();
158	    STATE.get_or_init(|| Mutex::new(AppleImportState::default()))
159	}
160	
161	/// Snapshot the current progress for the polling UI.
162	pub fn apple_import_snapshot() -> AppleImportState {
163	    import_state()
164	        .lock()
165	        .map(|state| state.clone())
166	        .unwrap_or_default()
167	}
168	
169	/// Claim the single import slot, resetting progress. Errors if one is running.
170	pub fn begin_apple_import(target_folder: String) -> Result<(), String> {
171	    let mut state = import_state()
172	        .lock()
173	        .map_err(|_| "Import state is unavailable.".to_string())?;
174	    if state.running {
175	        return Err("An import is already running.".to_string());
176	    }
177	    *state = AppleImportState {
178	        running: true,
179	        target_folder,
180	        ..Default::default()
181	    };
182	    Ok(())
183	}
184	
185	/// Mutate the shared progress state, ignoring lock poisoning.
186	fn with_state(update: impl FnOnce(&mut AppleImportState)) {
187	    if let Ok(mut state) = import_state().lock() {
188	        update(&mut state);
189	    }
190	}
191	
192	// ── Source scanning ──────────────────────────────────────────────────────────
193	
194	/// A single importable file plus its POSIX-style directory relative to the root.
195	struct ImportFile {
196	    path: PathBuf,
197	    rel_dir: String,
198	}
199	
200	/// Produce a preview of what an export folder contains.
201	pub fn scan_apple_import_source(source: &Path) -> Result<AppleImportScan, String> {
202	    if !source.exists() || !source.is_dir() {
203	        return Err("The selected path is not a folder.".to_string());
204	    }
205	    let (files, skipped) = collect_import_files(source);
206	    let mut folders: HashSet<String> = HashSet::new();
207	    for file in &files {
208	        if !file.rel_dir.is_empty() {
209	            folders.insert(file.rel_dir.clone());
210	        }
211	    }
212	    let sample_titles = files
213	        .iter()
214	        .take(6)
215	        .map(|file| title_from_path(&file.path))
216	        .collect();
217	    Ok(AppleImportScan {
218	        note_count: files.len() as u32,
219	        folder_count: folders.len() as u32,
220	        skipped_files: skipped,
221	        source_name: source
222	            .file_name()
223	            .map(|name| name.to_string_lossy().to_string())
224	            .filter(|name| !name.is_empty())
225	            .unwrap_or_else(|| DEFAULT_IMPORT_FOLDER.to_string()),
226	        sample_titles,
227	    })
228	}
