230	/// Walk the source tree, returning importable files and the count of files
231	/// skipped because they are not note text (attachments, images, …).
232	fn collect_import_files(source: &Path) -> (Vec<ImportFile>, u32) {
233	    let mut files = Vec::new();
234	    let mut skipped = 0u32;
235	    walk_dir(source, "", &mut files, &mut skipped);
236	    (files, skipped)
237	}
238	
239	fn walk_dir(dir: &Path, rel: &str, files: &mut Vec<ImportFile>, skipped: &mut u32) {
240	    let Ok(entries) = fs::read_dir(dir) else {
241	        return;
242	    };
243	    for entry in entries.flatten() {
244	        let name = entry.file_name().to_string_lossy().to_string();
245	        // Skip dotfiles (.DS_Store, .git, …) and the app's own order metadata.
246	        if name.starts_with('.') {
247	            continue;
248	        }
249	        let Ok(file_type) = entry.file_type() else {
250	            continue;
251	        };
252	        let path = entry.path();
253	        if file_type.is_dir() {
254	            let child_rel = if rel.is_empty() {
255	                name
256	            } else {
257	                format!("{}/{}", rel, name)
258	            };
259	            walk_dir(&path, &child_rel, files, skipped);
260	        } else if file_type.is_file() {
261	            if has_text_extension(&path) {
262	                files.push(ImportFile {
263	                    path,
264	                    rel_dir: rel.to_string(),
265	                });
266	            } else {
267	                *skipped += 1;
268	            }
269	        }
270	    }
271	}
272	
273	fn has_text_extension(path: &Path) -> bool {
274	    extension_lower(path)
275	        .map(|ext| TEXT_EXTENSIONS.contains(&ext.as_str()))
276	        .unwrap_or(false)
277	}
278	
279	fn extension_lower(path: &Path) -> Option<String> {
280	    path.extension()
281	        .map(|ext| ext.to_string_lossy().to_ascii_lowercase())
282	}
