292	
293	/// Per-note outcome.
294	enum Imported {
295	    Created,
296	}
297	
298	/// Run the import to completion, then mark the shared state finished. Spawned on
299	/// a detached worker thread by the command layer.
300	pub fn run_apple_notes_import(notes_root: PathBuf, args: AppleImportArgs) {
301	    let result = import_inner(&notes_root, &args);
302	    with_state(|state| {
303	        state.running = false;
304	        state.done = true;
305	        if let Err(err) = result {
306	            state.error = Some(err);
307	        }
308	    });
309	}
310	
311	fn import_inner(notes_root: &Path, args: &AppleImportArgs) -> Result<(), String> {
312	    let source = PathBuf::from(args.source_path.trim());
313	    if !source.is_dir() {
314	        return Err("The selected source folder no longer exists.".to_string());
315	    }
316	
317	    let base_target = match args.mode {
318	        AppleImportMode::Flatten => FEED_FOLDER.to_string(),
319	        AppleImportMode::Preserve => resolve_preserve_target(&source, args),
320	    };
321	
322	    // Reject a target that resolves into hidden storage (Recordings/attachments).
323	    if is_storage_folder_path(notes_root, &join_rel(notes_root, &base_target)) {
324	        return Err("Choose a different target folder — that name is reserved.".to_string());
325	    }
326	    with_state(|state| state.target_folder = base_target.clone());
327	
328	    let (files, _skipped) = collect_import_files(&source);
329	    with_state(|state| state.total = files.len() as u32);
330	
331	    let mut created_folders: HashSet<String> = HashSet::new();
332	    for file in &files {
333	        with_state(|state| state.current = title_from_path(&file.path));
334	        let outcome = import_one(notes_root, &base_target, args, file, &mut created_folders);
335	        with_state(|state| {
336	            state.processed += 1;
337	            match outcome {
338	                Ok(Imported::Created) => state.imported += 1,
339	                Err(ref err) => {
340	                    state.failed += 1;
341	                    if state.errors.len() < MAX_TRACKED_ERRORS {
342	                        state
343	                            .errors
344	                            .push(format!("{}: {}", title_from_path(&file.path), err));
345	                    }
346	                }
347	            }
348	            state.folders_created = created_folders.len() as u32;
349	        });
350	    }
351	    Ok(())
352	}
353	
354	fn import_one(
355	    notes_root: &Path,
356	    base_target: &str,
357	    args: &AppleImportArgs,
358	    file: &ImportFile,
359	    created_folders: &mut HashSet<String>,
360	) -> Result<Imported, String> {
361	    let parsed = read_and_parse_note(file)?;
362	
363	    let folder_rel = match args.mode {
364	        AppleImportMode::Flatten => FEED_FOLDER.to_string(),
365	        AppleImportMode::Preserve => {
366	            let sub = sanitize_rel_path(&file.rel_dir);
367	            if sub.is_empty() {
368	                base_target.to_string()
369	            } else {
370	                format!("{}/{}", base_target, sub)
371	            }
372	        }
373	    };
374	
375	    let folder_full = join_rel(notes_root, &folder_rel);
376	    if is_storage_folder_path(notes_root, &folder_full) {
377	        return Err("Destination resolves to reserved storage.".to_string());
378	    }
379	    fs::create_dir_all(&folder_full).map_err(|err| err.to_string())?;
380	    created_folders.insert(folder_rel);
381	
382	    let note_id = generate_note_id();
383	    let file_name = allocate_note_file_name(
384	        &folder_full,
385	        parsed.created_ms,
386	        &note_id,
387	        &parsed.body,
388	        "imported-note",
389	        args.file_name_format,
390	    )?;
391	    let path = folder_full.join(&file_name);
392	
393	    let meta = NoteFrontMatter {
394	        id: Some(note_id),
395	        created_ms: Some(parsed.created_ms),
396	        updated_ms: Some(parsed.created_ms),
397	        ..Default::default()
398	    };
399	    write_note_with_front_matter(&path, &meta, &parsed.body)?;
400	    if !is_feed_folder_path(notes_root, &folder_full) {
401	        update_order_append(&folder_full, std::slice::from_ref(&file_name), false)?;
402	    }
403	    Ok(Imported::Created)
404	}
