406	/// Resolve + sanitize the single top-level folder for `preserve` mode.
407	fn resolve_preserve_target(source: &Path, args: &AppleImportArgs) -> String {
408	    let requested = args
409	        .target_folder
410	        .as_deref()
411	        .map(str::trim)
412	        .filter(|value| !value.is_empty())
413	        .map(sanitize_segment)
414	        .filter(|value| !value.is_empty());
415	    requested
416	        .or_else(|| {
417	            source
418	                .file_name()
419	                .map(|name| sanitize_segment(&name.to_string_lossy()))
420	                .filter(|value| !value.is_empty())
421	        })
422	        .unwrap_or_else(|| DEFAULT_IMPORT_FOLDER.to_string())
423	}
