425	/// Join a POSIX-style relative path onto a root using native separators.
426	fn join_rel(root: &Path, rel: &str) -> PathBuf {
427	    let mut path = root.to_path_buf();
428	    for segment in rel.split('/') {
429	        if !segment.is_empty() {
430	            path.push(segment);
431	        }
432	    }
433	    path
434	}
435	
436	/// Strip characters that are illegal/awkward in folder names; returns "" if the
437	/// whole segment is unusable.
438	fn sanitize_segment(name: &str) -> String {
439	    let cleaned: String = name
440	        .chars()
441	        .map(|ch| match ch {
442	            '/' | '\\' | ':' | '*' | '?' | '"' | '<' | '>' | '|' => ' ',
443	            ch if ch.is_control() => ' ',
444	            ch => ch,
445	        })
446	        .collect();
447	    let trimmed = cleaned.trim().trim_matches('.').trim();
448	    if trimmed == "." || trimmed == ".." {
449	        return String::new();
450	    }
451	    trimmed.to_string()
452	}
453	
454	/// Sanitize each segment of a relative directory, dropping empties.
455	fn sanitize_rel_path(rel: &str) -> String {
456	    rel.split('/')
457	        .map(sanitize_segment)
458	        .filter(|segment| !segment.is_empty())
459	        .collect::<Vec<_>>()
460	        .join("/")
461	}
