587	// ── HTML → Markdown ──────────────────────────────────────────────────────────
588	
589	/// Best-effort HTML → Markdown for Apple Notes exports. Apple Notes HTML is
590	/// simple and regular (headings, paragraphs, `<div>`/`<br>` breaks, bold/italic,
591	/// lists, links), so a focused converter avoids pulling in a full HTML crate.
592	fn html_to_markdown(html: &str) -> String {
593	    let without_meta = strip_blocks(html, &["head", "style", "script"]);
594	    let with_links = rewrite_anchors(&without_meta);
595	
596	    let bytes = with_links.as_bytes();
597	    let mut out = String::with_capacity(with_links.len());
598	    let mut i = 0usize;
599	    while i < bytes.len() {
600	        if bytes[i] == b'<' {
601	            // Read to the closing '>'.
602	            let Some(end_rel) = with_links[i..].find('>') else {
603	                break;
604	            };
605	            let tag = &with_links[i + 1..i + end_rel];
606	            out.push_str(&render_tag(tag));
607	            i += end_rel + 1;
608	        } else {
609	            out.push(bytes[i] as char);
610	            i += 1;
611	        }
612	    }
613	
614	    let decoded = decode_entities(&out);
615	    collapse_whitespace(&decoded)
616	}
617	
618	/// Translate a single tag (contents between `<` and `>`) into Markdown glue.
619	fn render_tag(tag: &str) -> String {
620	    let trimmed = tag.trim();
621	    let is_close = trimmed.starts_with('/');
622	    let name: String = trimmed
623	        .trim_start_matches('/')
624	        .chars()
625	        .take_while(|c| c.is_ascii_alphanumeric())
626	        .collect::<String>()
627	        .to_ascii_lowercase();
628	
629	    match name.as_str() {
630	        "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
631	            if is_close {
632	                "\n\n".to_string()
633	            } else {
634	                let level = name[1..].parse::<usize>().unwrap_or(1);
635	                format!("\n{} ", "#".repeat(level))
636	            }
637	        }
638	        "br" => "\n".to_string(),
639	        "p" | "div" => "\n".to_string(),
640	        "li" => {
641	            if is_close {
642	                "\n".to_string()
643	            } else {
644	                "- ".to_string()
645	            }
646	        }
647	        "ul" | "ol" => "\n".to_string(),
648	        "blockquote" => {
649	            if is_close {
650	                "\n".to_string()
651	            } else {
652	                "\n> ".to_string()
653	            }
654	        }
655	        "b" | "strong" => "**".to_string(),
656	        "i" | "em" => "*".to_string(),
657	        "code" => "`".to_string(),
658	        _ => String::new(),
659	    }
660	}
661	
662	/// Rewrite `<a href="URL">TEXT</a>` into `[TEXT](URL)` before generic stripping.
663	fn rewrite_anchors(html: &str) -> String {
664	    let mut out = String::with_capacity(html.len());
665	    let lower = html.to_ascii_lowercase();
666	    let mut cursor = 0usize;
667	    while let Some(rel) = lower[cursor..].find("<a ") {
668	        let start = cursor + rel;
669	        out.push_str(&html[cursor..start]);
670	        // Find end of the opening tag.
671	        let Some(open_end_rel) = html[start..].find('>') else {
672	            out.push_str(&html[start..]);
673	            return out;
674	        };
675	        let open_end = start + open_end_rel;
676	        let open_tag = &html[start..=open_end];
677	        let href = extract_attr(open_tag, "href").unwrap_or_default();
678	        // Find the matching close.
679	        let Some(close_rel) = lower[open_end..].find("</a>") else {
680	            out.push_str(&html[start..]);
681	            return out;
682	        };
683	        let close = open_end + close_rel;
684	        let text = &html[open_end + 1..close];
685	        if href.is_empty() {
686	            out.push_str(text);
687	        } else {
688	            out.push_str(&format!("[{}]({})", text.trim(), href));
689	        }
690	        cursor = close + "</a>".len();
691	    }
692	    out.push_str(&html[cursor..]);
693	    out
694	}
695	
696	/// Pull a quoted attribute value out of an opening tag.
697	fn extract_attr(tag: &str, attr: &str) -> Option<String> {
698	    let lower = tag.to_ascii_lowercase();
699	    let key = format!("{}=", attr);
700	    let key_at = lower.find(&key)?;
701	    let after = &tag[key_at + key.len()..];
702	    let after = after.trim_start();
703	    let quote = after.chars().next()?;
704	    if quote == '"' || quote == '\'' {
705	        let rest = &after[1..];
706	        let end = rest.find(quote)?;
707	        Some(rest[..end].to_string())
708	    } else {
709	        Some(after.split_whitespace().next().unwrap_or("").to_string())
710	    }
711	}
712	
713	/// Remove whole `<tag>…</tag>` blocks (case-insensitive) for the given tag names.
714	fn strip_blocks(html: &str, tags: &[&str]) -> String {
715	    let mut result = html.to_string();
716	    for tag in tags {
717	        let lower = result.to_ascii_lowercase();
718	        let open = format!("<{}", tag);
719	        let close = format!("</{}>", tag);
720	        let mut out = String::with_capacity(result.len());
721	        let mut cursor = 0usize;
722	        let lower_ref = lower.as_str();
723	        while let Some(rel) = lower_ref[cursor..].find(&open) {
724	            let start = cursor + rel;
725	            out.push_str(&result[cursor..start]);
726	            if let Some(close_rel) = lower_ref[start..].find(&close) {
727	                cursor = start + close_rel + close.len();
728	            } else {
729	                cursor = result.len();
730	            }
731	        }
732	        out.push_str(&result[cursor..]);
733	        result = out;
734	    }
735	    result
736	}
737	
738	/// Decode the handful of HTML entities Apple Notes emits.
739	fn decode_entities(input: &str) -> String {
740	    let mut out = String::with_capacity(input.len());
741	    let mut rest = input;
742	    while let Some(idx) = rest.find('&') {
743	        out.push_str(&rest[..idx]);
744	        let tail = &rest[idx..];
745	        if let Some(semi) = tail.find(';').filter(|semi| *semi <= 10) {
746	            let entity = &tail[1..semi];
747	            let decoded = match entity {
748	                "amp" => Some('&'),
749	                "lt" => Some('<'),
750	                "gt" => Some('>'),
751	                "quot" => Some('"'),
752	                "apos" | "#39" => Some('\''),
753	                "nbsp" => Some(' '),
754	                _ => decode_numeric_entity(entity),
755	            };
756	            if let Some(ch) = decoded {
757	                out.push(ch);
758	                rest = &tail[semi + 1..];
759	                continue;
760	            }
761	        }
762	        out.push('&');
763	        rest = &tail[1..];
764	    }
765	    out.push_str(rest);
766	    out
767	}
768	
769	fn decode_numeric_entity(entity: &str) -> Option<char> {
770	    let code = if let Some(hex) = entity
771	        .strip_prefix("#x")
772	        .or_else(|| entity.strip_prefix("#X"))
773	    {
774	        u32::from_str_radix(hex, 16).ok()?
775	    } else if let Some(dec) = entity.strip_prefix('#') {
776	        dec.parse::<u32>().ok()?
777	    } else {
778	        return None;
779	    };
780	    char::from_u32(code)
781	}
782	
783	/// Trim trailing spaces and collapse runs of blank lines down to one.
784	fn collapse_whitespace(input: &str) -> String {
785	    let mut lines: Vec<String> = input
786	        .replace('\r', "")
787	        .split('\n')
788	        .map(|line| line.trim_end().to_string())
789	        .collect();
790	    // Collapse 2+ consecutive blank lines into a single blank line.
791	    let mut collapsed: Vec<String> = Vec::with_capacity(lines.len());
792	    let mut blank_run = false;
793	    for line in lines.drain(..) {
794	        if line.is_empty() {
795	            if !blank_run {
796	                collapsed.push(line);
797	            }
798	            blank_run = true;
799	        } else {
800	            collapsed.push(line);
801	            blank_run = false;
802	        }
803	    }
804	    collapsed.join("\n").trim().to_string()
805	}
